insert into public.guria_quick_replies (trigger_key, patterns, response, priority) values
('dc_greatest_hero', array['maior.*her[oó]i.*dc', 'melhor.*her[oó]i.*dc', 'quem.*maior.*dc', 'maior personagem da dc'], 'Pergunta perigosa, dessas que fazem duas pessoas saírem de uma conversa tranquila e entrarem numa guerra de torcida. Para mim, o Superman é o maior símbolo da DC: representa esperança, tem uma história enorme e praticamente ajudou a definir o gênero. Mas o Batman ganha em preparo, e a Mulher-Maravilha ganha em presença. Então a resposta honesta é: Superman como ícone, Batman como estrategista e Mulher-Maravilha como lenda.', 100)
